 x={'event_type':kind,'schema_version':'1.0','paper_id':PID,'revision':'r15',**payload,'scientific_authority':False,'experiment_authority':False,'gpu_authority':False,'submission_authority':False};x['receipt_sha256']=_digest({k:v for k,v in x.items() if k!='receipt_sha256'});_append(root,c,'temporal-r15-targeted-repair',x);return x
