 event(a.root,c,'source-native-r15-finalization',{'receipt_type':'source-native-finalization','artifact_ref':A(PM),'title':TITLE,'paper_pdf_sha256':PDF,'source_zip_sha256':SRC,'supplement_zip_sha256':SUP,'source_native_runtime_valid_rows':2056,'distinct_endpoints':35,'institutional_systems':3,'exact_timesage_replication_debt':'ACTIVE_EXTERNAL_REPLICATION_DEBT_NOT_SUBSTITUTED','recommended_immediate_action':'READY_FOR_HUMAN_SUBMISSION','new_scientific_model_calls':0,'new_provider_calls':0,'external_review_textual_verdict':'Accept','external_review_numeric_nonofficial':6.0,'claim_expansion':False,'contract_revision':False})
